# Simple transformation: apply template colors to 8-cells
# Each 8-cell's color = color from template at same normalized position

color_map = {0: 0, 1: 2, 2: 2, 3: 1, 4: 3}  # Template to output colors

def transform(grid):
    result = [[0] * len(grid[0]) for _ in range(len(grid))]

    # Find template and its bounding box
    template_cells = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and grid[r][c] != 8:
                template_cells.append((r, c, grid[r][c]))

    if not template_cells:
        return result

    min_t_r, max_t_r = min(t[0] for t in template_cells), max(t[0] for t in template_cells)
    min_t_c, max_t_c = min(t[1] for t in template_cells), max(t[1] for t in template_cells)

    # Extract template
    template = [[grid[r][c] for c in range(min_t_c, max_t_c+1)] for r in range(min_t_r, max_t_r+1)]

    # Find 8-cells and their bounding box
    cells_8 = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 8:
                cells_8.append((r, c))

    min_8_r, max_8_r = min(r for r, c in cells_8), max(r for r, c in cells_8)
    min_8_c, max_8_c = min(c for r, c in cells_8), max(c for r, c in cells_8)

    # For each 8-cell, map to template position and apply color
    for r in range(min_8_r, max_8_r+1):
        for c in range(min_8_c, max_8_c+1):
            if grid[r][c] == 8:
                # Compute normalized position
                nr = r - min_8_r  # 0-indexed mapped position
                nc = c - min_8_c

                # Map to template: template is (template_rows x template_cols)
                tr = nr % len(template)
                tc = nc % len(template[0])

                template_val = template[tr][tc]
                result[r][c] = color_map.get(template_val, template_val)

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and grid[r][c] != 8:
                result[r][c] = grid[r][c]  # Keep template
            elif grid[r][c] == 0:
                pass  # or 0

    return result

